import React, { useState, useEffect } from "react";
import "../App.css";

function Home() {
  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [template, setTemplate] = useState("simple");
  const [matchData, setMatchData] = useState(null);
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) window.location.href = "/login";
  }, []);

  const handleAuthError = (res) => {
    if (res.status === 401) {
      alert("Session expired. Login again.");
      localStorage.removeItem("token");
      window.location.href = "/login";
      return true;
    }
    return false;
  };

  // ================= OPTIMIZE =================
  const handleOptimize = async () => {
    if (!resumeText.trim() || !jobDesc.trim()) {
      return alert("Provide Resume + JD");
    }

    setLoading(true);
    setMatchData(null);

    try {
      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
          template,
        }),
      });

      if (handleAuthError(res)) return;

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Optimization failed");
        return;
      }

      setResult(data);
    } catch (err) {
      console.error(err);
      alert("Server error");
    }

    setLoading(false);
  };

  // ================= MATCH =================
  const handleMatch = async () => {
    if (!resumeText.trim()) {
      alert("Provide resume first");
      return;
    }

    try {
      const res = await fetch("http://localhost:5000/api/resume/match", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
        }),
      });

      if (handleAuthError(res)) return;

      const data = await res.json();
      console.log("MATCH RESPONSE:", data);

      if (!res.ok) {
        alert(data.msg || "Match failed");
        return;
      }

      setMatchData(data);
    } catch (err) {
      console.error(err);
      alert("Match error");
    }
  };

  // ================= SAVE =================
  const handleSave = async () => {
    if (!result) return alert("Optimize first");

    try {
      const res = await fetch("http://localhost:5000/api/resume/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          text: result.optimizedText,
          atsScore: result.score,
        }),
      });

      if (handleAuthError(res)) return;

      alert("Saved successfully");
    } catch {
      alert("Save failed");
    }
  };

  // ================= PDF UPLOAD =================
  const uploadPDF = async (file, setState, label) => {
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://localhost:5000/api/resume/upload-pdf", {
        method: "POST",
        headers: {
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: formData,
      });

      if (handleAuthError(res)) return;

      const data = await res.json();

      if (!data.text) {
        alert(label + " parsing failed");
        return;
      }

      setState(data.text);
      alert(label + " loaded");
    } catch {
      alert("Upload error");
    }
  };

  const handleResumeUpload = (e) => {
    if (e.target.files[0])
      uploadPDF(e.target.files[0], setResumeText, "Resume");
  };

  const handleJDUpload = (e) => {
    if (e.target.files[0])
      uploadPDF(e.target.files[0], setJobDesc, "JD");
  };

  // ================= PHOTO (FIXED) =================
  const handlePhoto = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();

    reader.onloadend = () => {
      const base64 = reader.result.split(",")[1];
      setPhoto(base64);
      setPhotoPreview(reader.result); // 🔥 PREVIEW
    };

    reader.readAsDataURL(file);
  };

  // ================= DOWNLOAD =================
  const handleDownload = async () => {
    if (!result) return alert("Optimize first");

    try {
      const res = await fetch("http://localhost:5000/api/resume/download", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          text: result.optimizedText,
          photo,
          template,
        }),
      });

      if (handleAuthError(res)) return;

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();
    } catch {
      alert("Download failed");
    }
  };

  return (
    <div className="container">
      <h1>CareerForge Pro 🚀</h1>

      <div className="card">
        <h3>Resume</h3>
        <input type="file" accept=".pdf" onChange={handleResumeUpload} />
        <textarea
          placeholder="Paste Resume..."
          value={resumeText}
          onChange={(e) => setResumeText(e.target.value)}
        />

        <h3>Job Description</h3>
        <input type="file" accept=".pdf" onChange={handleJDUpload} />
        <textarea
          placeholder="Paste JD..."
          value={jobDesc}
          onChange={(e) => setJobDesc(e.target.value)}
        />

        <h3>Upload Photo</h3>
        <input type="file" accept="image/*" onChange={handlePhoto} />

        {/* 🔥 PREVIEW */}
        {photoPreview && (
          <img
            src={photoPreview}
            alt="preview"
            style={{ width: "80px", marginTop: "10px", borderRadius: "6px" }}
          />
        )}

        <select value={template} onChange={(e) => setTemplate(e.target.value)}>
          <option value="simple">Simple</option>
          <option value="modern">Modern</option>
          <option value="professional">Professional</option>
        </select>

        <button className="button-primary" onClick={handleOptimize}>
          {loading ? "Optimizing..." : "Optimize Resume"}
        </button>

        <button className="button-secondary" onClick={handleMatch}>
          Check Job Match
        </button>
      </div>

      {/* RESULT */}
      {result && (
        <div className="result-card">
          <h2>ATS Score: {result.score}</h2>

          <div className="output-box">
  <pre style={{ whiteSpace: "pre-wrap", lineHeight: "1.6" }}>
    {result.optimizedText}
  </pre>
</div>
          <button className="button-primary" onClick={handleSave}>
            Save Resume
          </button>

          <button className="button-primary" onClick={handleDownload}>
            Download PDF
          </button>
          <button className="button-secondary" onClick={() => (window.location.href = "/dashboard")}>
          Go to Dashboard
          </button>
        </div>
      )}

      {/* MATCH */}
      {matchData && (
  <div className="result-card">
    <h2>🎯 Match Score: {matchData.matchScore}%</h2>

    <div className="skills-section">
      <div>
        <h3>✅ Matched Skills</h3>
        <ul>
          {matchData.matchedSkills.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
      </div>

      <div>
        <h3>❌ Missing Skills</h3>
        <ul>
          {matchData.missingSkills.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
      </div>
    </div>

    <h3>🏢 Job Opportunities</h3>
    {matchData.recommendations.map((job, i) => (
      <div key={i} className="job-card">
        <div className="job-row">
          <span>{job.company}</span>
          <span className="chance">{job.chance}%</span>
        </div>
        <div className="progress">
          <div
            className="progress-bar"
            style={{ width: `${job.chance}%` }}
          ></div>
        </div>
      </div>
    ))}
  </div>
)}
    </div>
  );
}

export default Home;
